package com.jinloes.practice;
import java.util.Arrays; import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: two equal-length height arrays, for example: [5, 8, 1] [6, 9, 2]"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) { runInput(String.join(" ", args).trim()); return; } assertThat(Solution.canTakePhoto(new int[]{5,8,1},new int[]{6,9,2})).isTrue(); assertThat(Solution.canTakePhoto(new int[]{5,8,1},new int[]{6,7,2})).isFalse(); assertThat(Solution.canTakePhoto(new int[]{3,4},new int[]{4,3})).isFalse(); System.out.println("Examples passed: 3"); } private static void runInput(String input){ try{ int split=input.indexOf(']', input.indexOf('['))+1; int[] a=parse(input.substring(0,split)); int[] b=parse(input.substring(split)); System.out.println(Solution.canTakePhoto(a,b)); }catch(RuntimeException e){ System.out.println(USAGE); } } static int[] parse(String t){ String c=t.replace('[',' ').replace(']',' ').replace(',',' ').trim(); if(c.isEmpty()) return new int[0]; return Arrays.stream(c.split("\\s+")).mapToInt(Integer::parseInt).toArray(); } }
